grid.scripts:

function load$Grid(g) {
  g.$a = {
    tien_nt2_sl: '[tien_nt2]:=[so_luong]*[gia_nt]',
    tien2: '[tien2]:=[tien_nt2]*[$ty_gia]',
    ck_nt: '[ck_nt]:=[tien_nt2]*[tl_ck]/100',
    thue_nt: '[thue_nt]:=([tien_nt2] - [ck_nt])*[thue_suat]/100',
    tien_mthang_nt: '[tien_mthang_nt]:=([phi_dvtn_yn] == 0 ? [tien_nt2] : 0)',
    t_tien_hang_nt: ['t_tien_hang_nt', 'tien_mthang_nt'],
    t_ck_nt: ['t_ck_nt', 'ck_nt'],
    t_thue_nt: ['t_thue_nt', 'thue_nt', '[phi_dvtn_yn] == 0'],
    t_thue_dvtn_nt: ['t_thue_dvtn_nt', 'thue_nt', '[phi_dvtn_yn] != 0'],
    t_tt_nt: '[t_tt_nt]:=[t_tien_hang_nt]-[t_ck_nt]+[t_thue_nt]'
  };
}

function onChange$GridVoucherDetail$(o) {
  var name = o.field.Name;
  var g = o.grid;
  switch (name) {
    case 'so_luong':
      g.validExpression(o, [g.$a.tien_nt2_sl, g.$a.tien2, g.$a.ck_nt, g.$a.thue_nt], [g.$a.t_tien_hang_nt, g.$a.t_ck_nt], [g.$a.t_tt_nt]);
      break;
    case 'gia_nt':
      g.validExpression(o, [g.$a.tien_nt2_sl, g.$a.tien2, g.$a.ck_nt, g.$a.thue_nt]);
      break;
    case 'phi_dvtn_yn':
      g.validExpression(o, [g.$a.tien_mthang_nt], [g.$a.t_tien_hang_nt]);
      break;
  }
}
